mapper.select:
SELECT  FROM ddc_instance
WHERE tenant_id = #{tenantId} AND biz_code = #{bizCode} AND env = #{env} AND app_code = #{appCode}
  AND deleted_at IS NULL
ORDER BY updated_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE ddc_instance SET status = #{status}, updated_at = #{updatedAt}, version = version + 1,
    update_user_id = #{actor}, update_time = #{updateTime}
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{expectedVersion}
  AND instance_id = #{instanceId} AND lease_id = #{leaseId}
  AND deleted_at IS NULL

UPDATE ddc_instance SET status = 'OFFLINE', updated_at = #{updatedAt}, version = version + 1,
    update_user_id = #{actor}, update_time = #{updateTime}
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{expectedVersion}
  AND resource_server_id = #{resourceServerId}
  AND biz_code = #{bizCode} AND env = #{env} AND app_code = #{appCode}
  AND resource_version <= #{resourceVersion} AND status = 'ONLINE' AND deleted_at IS NULL

UPDATE ddc_instance SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime}
WHERE tenant_id = #{et.tenantId} AND id = #{et.id} AND version = #{et.version} AND deleted_at IS NULL
